import { useEffect, useMemo, useState } from "react";
import { fetchAllChestShops, fetchWarpZones } from "@/lib/castiaClient";
import { exactCoins, nearbyShops, parseShopLocation, sameShopPosition, shopLocationKey } from "@/lib/shopLocation";
import { distinctShopRows, stockLabel, stockTimestamp } from "@/lib/shopStock";

let catalogCache = null;

export default function ShopLocationPanel({ locationKey, onClose, onSelect, onCompare }) {
  const target = useMemo(() => parseShopLocation(locationKey), [locationKey]);
  const [catalog, setCatalog] = useState(null);
  const [zones, setZones] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refresh, setRefresh] = useState(0);
  const [copied, setCopied] = useState("");
  const [height, setHeight] = useState(target?.y ?? 0);

  useEffect(() => {
    if (!target) { setLoading(false); return; }
    const controller = new AbortController();
    setLoading(true); setError(null);
    const cached = !refresh && catalogCache && Date.now() - catalogCache.at < 60000;
    Promise.all([
      cached ? Promise.resolve(catalogCache.rows) : fetchAllChestShops({ signal: controller.signal }).then(result => distinctShopRows(result.shops)),
      fetchWarpZones({ limit: 500, signal: controller.signal }).then(result => result.zones || []).catch(() => []),
    ]).then(([rows, arrivals]) => {
      if (controller.signal.aborted) return;
      if (!cached) catalogCache = { at: Date.now(), rows };
      setCatalog(rows); setZones(arrivals);
    }).catch(e => { if (!controller.signal.aborted) setError(e.message); })
      .finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [target, refresh]);

  const selected = target && catalog?.find(row => sameShopPosition(row, target));
  const replaced = selected && target.signFingerprint && selected.signFingerprint !== target.signFingerprint;
  const nearby = useMemo(() => target ? nearbyShops(catalog || [], target) : [], [catalog, target]);
  const levels = [...new Set([target?.y ?? 0, ...nearby.map(row => row.y)])].sort((a, b) => a - b);
  const band = nearby.filter(row => Math.abs(row.y - height) <= 2);
  const arrivals = target ? zones.filter(zone => zone.serverKey === target.serverKey && zone.dimensionKey === target.dimensionKey
    && Math.hypot(zone.centerX - target.x, zone.centerZ - target.z) <= 64 && Math.abs(zone.centerY - height) <= 2) : [];
  const copy = async (text, label) => {
    try { await navigator.clipboard.writeText(text); setCopied(`${label} copied`); }
    catch { setCopied(`Copy manually: ${text}`); }
  };
  const buttonClass = "px-3 py-2 rounded border border-white/20 text-sm hover:bg-white/10 focus-visible:outline focus-visible:outline-2 focus-visible:outline-indigo-400";

  return <div className="h-full overflow-y-auto p-5 sm:p-8 space-y-5" data-testid="shop-location-panel">
    <div className="flex justify-between items-center gap-3">
      <h2 className="text-xl font-bold">Chest-shop location</h2>
      <button className={buttonClass} data-testid="drawer-close" onClick={onClose}>Close</button>
    </div>
    {!target ? <p>This location link is invalid.</p> : <>
      <p className="text-sm text-zinc-300 break-words">{target.serverKey} · {target.dimensionKey.replace("minecraft:", "")}<br />
        Sign at X {target.x}, Y {target.y}, Z {target.z} · Chunk {Math.floor(target.x / 16)}, {Math.floor(target.z / 16)}</p>
      <div className="flex flex-wrap gap-2">
        <button className={buttonClass} onClick={() => copy(`${target.x}, ${target.y}, ${target.z}`, "Coordinates")}>Copy coordinates</button>
        <button className={buttonClass} onClick={() => copy(window.location.href, "Location link")}>Share location</button>
        <button className={buttonClass} disabled={loading} onClick={() => setRefresh(value => value + 1)}>Refresh observations</button>
      </div>
      <p role="status" className="text-sm text-indigo-300 break-words">{copied}</p>
      {loading && <p role="status">Loading observed offers…</p>}
      {error && <p role="alert">Could not load this location: {error}</p>}
      {!loading && !error && !selected && <p>No current observation exists at this location. The shop may have moved or may need rescanning.</p>}
      {!loading && !error && selected && <>
        {replaced && <p role="alert" className="border border-amber-400/50 p-3 text-amber-200">The sign has changed since this link was created. These are the current observations, not the original offer.</p>}
        <section className="rounded-xl border border-indigo-400/40 p-4 space-y-2">
          <h3 className="text-xl font-bold">{selected.itemName || selected.displayItemName}</h3>
          <p>Seller: {selected.seller}</p>
          <p className="text-indigo-300 font-bold">{exactCoins(selected.unitPrice)} coins each</p>
          <p>{exactCoins(selected.buyPrice)} coins per purchase of {selected.buyQuantity}</p>
          {selected.tier > 0 && <p>Tier {selected.tier}</p>}
          {Object.entries(selected.enchantments || {}).length > 0 && <p className="text-sm">{Object.entries(selected.enchantments).map(([name, level]) => `${name.replace("minecraft:", "").replaceAll("_", " ")} ${level}`).join(" · ")}</p>}
          <p>{stockLabel(selected)}</p><p className="text-sm text-zinc-400">{stockTimestamp(selected)}</p>
          {selected.requiresTooltipConfirmation && <p className="text-amber-200">Item identity still needs an in-game confirmation.</p>}
          <button className={buttonClass} onClick={() => onCompare(selected)}>Compare this item’s offers</button>
        </section>
      </>}
      {!loading && !error && catalog && <section className="space-y-3">
        <h3 className="text-lg font-bold">Nearby observed signs</h3>
        <p className="text-sm text-zinc-400">Coordinate map within 64 blocks. Grid lines mark 16-block chunks. Empty space is not surveyed terrain; dots do not establish shop ownership or a walkable route.</p>
        <label className="flex items-center gap-3 text-sm">Height band (Y ±2)
          <select aria-label="Map height band" className="bg-bg-base border border-white/20 rounded p-2" value={height} onChange={event => setHeight(Number(event.target.value))}>
            {levels.map(level => <option key={level} value={level}>{level}</option>)}
          </select>
        </label>
        <p className="text-sm text-zinc-300">North ↑ (−Z) · East → (+X). {Math.abs(height - target.y) > 2 ? `Selected sign is at Y ${target.y}, outside this band.` : "Selected sign: outlined square. Other offers: circles. Warp arrivals: triangles."}</p>
        <svg viewBox="0 0 320 320" role="group" aria-label="Coordinate map of observed signs and warp arrivals" className="w-full rounded-lg bg-white/[0.03] border border-white/10">
          <title>Nearby observed signs; use the offer buttons below to select a location</title>
          {Array.from({ length: 9 }, (_, i) => Math.floor((target.x - 64) / 16) * 16 + i * 16).map(x => <line key={`x${x}`} x1={160 + (x - target.x) * 2} x2={160 + (x - target.x) * 2} y1="16" y2="304" stroke="#3f3f46" />)}
          {Array.from({ length: 9 }, (_, i) => Math.floor((target.z - 64) / 16) * 16 + i * 16).map(z => <line key={`z${z}`} y1={160 + (z - target.z) * 2} y2={160 + (z - target.z) * 2} x1="16" x2="304" stroke="#3f3f46" />)}
          {band.map(row => <a key={shopLocationKey(row)} href={`?shopLocation=${encodeURIComponent(shopLocationKey(row))}`}
            aria-label={`${row.itemName} by ${row.seller} at ${row.x}, ${row.y}, ${row.z}`}
            onClick={event => { event.preventDefault(); onSelect(row); }}>
            <circle cx={160 + (row.x - target.x) * 2} cy={160 + (row.z - target.z) * 2} r="4" fill={row.stockCount > 0 ? "#a5b4fc" : "#a1a1aa"}><title>{row.itemName} · {row.seller} · Y {row.y}</title></circle>
          </a>)}
          {arrivals.map(zone => <path key={zone.id} transform={`translate(${160 + (zone.centerX - target.x) * 2} ${160 + (zone.centerZ - target.z) * 2})`} d="M0 -5L5 4H-5Z" fill="#fbbf24"><title>Arrival: {zone.warpName}</title></path>)}
          {Math.abs(height - target.y) <= 2 && <rect x="154" y="154" width="12" height="12" fill="none" stroke="#fff" strokeWidth="2" />}
        </svg>
        {arrivals.map(zone => <p key={zone.id} className="text-sm">Nearby arrival: <strong>{zone.warpName}</strong>{zone.shopAreaName ? ` · Area: ${zone.shopAreaName}` : ""} at Y {zone.centerY}. Proximity does not confirm this shop belongs to that warp.
          {/^[a-zA-Z0-9_-]+$/.test(zone.warpName) && <button className={`${buttonClass} ml-2`} onClick={() => copy(`/pw ${zone.warpName}`, "Warp command")}>Copy /pw command</button>}
        </p>)}
        <p className="text-sm text-zinc-400">{band.length} signs in this height band. Choose an offer below to move the selection.</p>
        <div className="max-h-72 overflow-y-auto space-y-2">
          {band.map(row => <button key={shopLocationKey(row)} onClick={() => onSelect(row)} className={`${buttonClass} w-full text-left`}>
            {row.itemName || row.displayItemName} · {row.seller} · {exactCoins(row.unitPrice)} each<br />
            <span className="text-zinc-400">X {row.x}, Y {row.y}, Z {row.z} · {stockLabel(row)}</span>
          </button>)}
        </div>
      </section>}
    </>}
  </div>;
}
